-- ADR-004, 4c: the user's legal name in Arabic, as written on the national ID
-- card, on every verification submission, for the reviewer to compare with the
-- card photo. Generated by drizzle-kit, with two hand edits (marked below).
--
-- Hand edit 1: drizzle-kit emits `ADD COLUMN ... NOT NULL`, which fails on a
-- table that already has rows. No production or staging data exists, but local
-- and test databases may hold synthetic submissions. The column is added with
-- a temporary constant default (PostgreSQL 11+ stores it as metadata: no table
-- rewrite, no long lock) that satisfies both CHECKs, and the default is dropped
-- in the same migration, so every later insert must supply the name. Existing
-- local rows read "الاسم غير مسجل" ("name not recorded"); nothing is deleted.
ALTER TABLE "verification_submission" ADD COLUMN "legal_name_ar" text DEFAULT 'الاسم غير مسجل' NOT NULL;--> statement-breakpoint
ALTER TABLE "verification_submission" ALTER COLUMN "legal_name_ar" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "verification_submission" ADD CONSTRAINT "verification_submission_legal_name_ar_length_check" CHECK (char_length(legal_name_ar) between 5 and 120);--> statement-breakpoint
ALTER TABLE "verification_submission" ADD CONSTRAINT "verification_submission_legal_name_ar_shape_check" CHECK (legal_name_ar ~ '^[ء-غف-يٱ]+(?:[-''][ء-غف-يٱ]+)*(?: [ء-غف-يٱ]+(?:[-''][ء-غف-يٱ]+)*){2,}$');--> statement-breakpoint
-- Hand edit 2: the submission guard from 0004, unchanged except that
-- legal_name_ar joins the columns that never change after insert.
CREATE OR REPLACE FUNCTION "verification_submission_guard"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.credential_type IS DISTINCT FROM OLD.credential_type
     OR NEW.legal_name_ar IS DISTINCT FROM OLD.legal_name_ar
     OR NEW.syndicate_number IS DISTINCT FROM OLD.syndicate_number
     OR NEW.university IS DISTINCT FROM OLD.university
     OR NEW.card_expires_on IS DISTINCT FROM OLD.card_expires_on
     OR NEW.national_id_ciphertext IS DISTINCT FROM OLD.national_id_ciphertext
     OR NEW.national_id_hash IS DISTINCT FROM OLD.national_id_hash
     OR NEW.national_id_masked IS DISTINCT FROM OLD.national_id_masked
     OR NEW.key_id IS DISTINCT FROM OLD.key_id
     OR NEW.consent_version IS DISTINCT FROM OLD.consent_version
     OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at THEN
    RAISE EXCEPTION 'verification_submission: immutable column changed' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
       (OLD.status = 'pending' AND NEW.status IN ('verified', 'rejected'))
    OR (OLD.status = 'verified' AND NEW.status = 'expired')
  ) THEN
    RAISE EXCEPTION 'verification_submission: transition % -> % not allowed', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
